from odoo import api, fields, models, _
from odoo.exceptions import ValidationError, UserError


class HrAppraisalSurveyQuestion(models.Model):
    """Survey Questions configured and generated by Top-Level Managers."""
    _name = 'hr.appraisal.survey.question'
    _description = 'Appraisal Survey Question (Manager Setup)'
    _order = 'sequence, id'

    name = fields.Char(
        string='Question', required=True, translate=True,
        help="Evaluation question generated by top-level management.")
    description = fields.Text(
        string='Guidelines / Context',
        help="Guidance notes or instructions for the respondent.")
    survey_type = fields.Selection([
        ('all', 'All Survey Types'),
        ('self', 'Self Assessment'),
        ('peer', 'Peer Assessment'),
        ('manager', 'Manager Evaluation'),
    ], string='Applies to Survey Type', default='all', required=True,
       help="Determines which survey type this question will be automatically loaded into.")
    job_id = fields.Many2one(
        'hr.job', string='Target Job Position',
        help="If set, this question only applies to employees in this job position. Leave empty for company-wide questions.")
    sequence = fields.Integer(string='Sequence', default=10)
    rating_scale_min = fields.Integer(string='Min Rating', default=1)
    rating_scale_max = fields.Integer(string='Max Rating', default=5)
    rating_label_min = fields.Char(string='Min Scale Label', default='Poor')
    rating_label_max = fields.Char(string='Max Scale Label', default='Excellent')
    is_required = fields.Boolean(string='Required', default=True)
    active = fields.Boolean(default=True)
    company_id = fields.Many2one(
        'res.company', string='Company', default=lambda self: self.env.company)
    manager_id = fields.Many2one(
        'res.users', string='Authoring Manager', default=lambda self: self.env.user,
        readonly=True, help="Top-level manager who authored this appraisal question.")


class HrAppraisalSurvey(models.Model):
    """Google Forms-styled Appraisal Survey Popup & Evaluation Record."""
    _name = 'hr.appraisal.survey'
    _description = 'Appraisal Survey Assessment'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _order = 'id desc'

    name = fields.Char(
        string='Survey Title', compute='_compute_name', store=True, readonly=False, tracking=True)

    # --- Respondent Information (Only require Job position & Survey type) ---
    job_id = fields.Many2one(
        'hr.job', string='Job Position', tracking=True,
        default=lambda self: self.env['hr.job'].search([], limit=1),
        help="Job position of the evaluated employee.")
    survey_type = fields.Selection([
        ('self', 'Self Assessment'),
        ('peer', 'Peer Assessment'),
        ('manager', 'Manager Evaluation'),
    ], string='Survey Type', required=True, default='self', tracking=True,
       help="Select which of the 3 appraisal survey types is being completed.")

    # --- Submission Date (Recorded but HIDDEN from survey popup view) ---
    date_submission = fields.Datetime(
        string='Date of Submission', readonly=True, copy=False, tracking=True,
        help="Automatically recorded when submitted; hidden from the respondent form.")

    # --- Context & Linkages ---
    appraisal_id = fields.Many2one(
        'hr.appraisal', string='Appraisal Cycle', ondelete='cascade',
        index=True, tracking=True)
    employee_id = fields.Many2one(
        'hr.employee', string='Employee Appraised', tracking=True)
    respondent_id = fields.Many2one(
        'hr.employee', string='Reviewer / Respondent',
        default=lambda self: self.env.user.employee_id, tracking=True)
    company_id = fields.Many2one(
        'res.company', string='Company', default=lambda self: self.env.company)

    # --- Status & Scoring ---
    state = fields.Selection([
        ('draft', 'Draft / In Progress'),
        ('submitted', 'Submitted'),
    ], string='Status', default='draft', required=True, tracking=True)
    score = fields.Float(
        string='Average Score (1-5)', compute='_compute_score', store=True, digits=(3, 2))
    general_feedback = fields.Text(
        string='Overall Feedback & Reflections',
        help="Provide general feedback, takeaways, achievements, or recommendations.")

    # --- Survey Questions with Rating Scale ---
    answer_ids = fields.One2many(
        'hr.appraisal.survey.answer', 'survey_id', string='Survey Responses', copy=True)
    answer_count = fields.Integer(
        string='Question Count', compute='_compute_answer_count')

    @api.depends('survey_type', 'job_id.name', 'employee_id.name')
    def _compute_name(self):
        type_labels = {
            'self': _('Self Assessment'),
            'peer': _('Peer Assessment'),
            'manager': _('Manager Evaluation'),
        }
        for rec in self:
            label = type_labels.get(rec.survey_type, _('Survey'))
            job_name = rec.job_id.name if rec.job_id else ''
            emp_name = rec.employee_id.name if rec.employee_id else ''
            if emp_name and job_name:
                rec.name = f"[{label}] {emp_name} ({job_name})"
            elif job_name:
                rec.name = f"[{label}] - {job_name}"
            else:
                rec.name = f"[{label}]"

    @api.depends('answer_ids.rating_value')
    def _compute_score(self):
        for rec in self:
            rated_answers = rec.answer_ids.filtered(lambda a: a.rating_value > 0)
            if rated_answers:
                rec.score = sum(rated_answers.mapped('rating_value')) / len(rated_answers)
            else:
                rec.score = 0.0

    @api.depends('answer_ids')
    def _compute_answer_count(self):
        for rec in self:
            rec.answer_count = len(rec.answer_ids)

    @api.onchange('job_id', 'survey_type')
    def _onchange_job_or_type_populate_questions(self):
        """Automatically load questions generated by top-level managers."""
        if self.survey_type:
            self.action_load_questions()

    def action_load_questions(self):
        """Populates survey answer lines from top-level manager questions."""
        self.ensure_one()
        Question = self.env['hr.appraisal.survey.question']
        domain = [
            ('active', '=', True),
            ('survey_type', 'in', [self.survey_type, 'all']),
        ]
        if self.job_id:
            domain.append(('job_id', 'in', [False, self.job_id.id]))
        else:
            domain.append(('job_id', '=', False))

        questions = Question.search(domain, order='sequence, id')
        existing_q_ids = self.answer_ids.mapped('question_id.id')
        new_lines = []
        for q in questions:
            if q.id not in existing_q_ids:
                new_lines.append((0, 0, {
                    'question_id': q.id,
                }))
        if new_lines:
            self.write({'answer_ids': new_lines})

    def action_submit(self):
        """Submits the survey, validating required rating scales and recording submission date."""
        for rec in self:
            if not rec.job_id:
                raise ValidationError(_("Please specify your Job Position before submitting."))
            missing_ratings = rec.answer_ids.filtered(
                lambda a: a.is_required and not a.rating
            )
            if missing_ratings:
                q_names = ", ".join(missing_ratings.mapped('question_id.name')[:3])
                raise ValidationError(_("Please select a rating for all required questions: %s", q_names))

            rec.write({
                'state': 'submitted',
                'date_submission': fields.Datetime.now(),
            })

            type_label = dict(rec._fields['survey_type'].selection).get(rec.survey_type, rec.survey_type)
            msg = _("Survey <b>%s</b> submitted for <b>%s</b> with overall score <b>%.2f/5.0</b>.",
                    type_label, rec.job_id.name if rec.job_id else _('Staff'), rec.score)
            rec.message_post(body=msg)
            if rec.appraisal_id:
                rec.appraisal_id.message_post(body=msg)

        return {'type': 'ir.actions.act_window_close'}

    def action_open_popup(self):
        """Opens this survey in a modal popup window."""
        self.ensure_one()
        return {
            'name': self.name,
            'type': 'ir.actions.act_window',
            'res_model': 'hr.appraisal.survey',
            'res_id': self.id,
            'view_mode': 'form',
            'target': 'new',
        }


class HrAppraisalSurveyAnswer(models.Model):
    """Question Answer Line with Rating Scale."""
    _name = 'hr.appraisal.survey.answer'
    _description = 'Survey Question Response & Rating'
    _order = 'sequence, id'

    survey_id = fields.Many2one(
        'hr.appraisal.survey', string='Survey', required=True, ondelete='cascade', index=True)
    question_id = fields.Many2one(
        'hr.appraisal.survey.question', string='Question', required=True, ondelete='cascade')
    question_name = fields.Char(
        string='Question Text', related='question_id.name', readonly=True)
    description = fields.Text(
        string='Guidelines', related='question_id.description', readonly=True)
    sequence = fields.Integer(
        string='Sequence', related='question_id.sequence', store=True)
    is_required = fields.Boolean(
        string='Required', related='question_id.is_required', readonly=True)
    rating_scale_min = fields.Integer(
        string='Min Scale', related='question_id.rating_scale_min', readonly=True)
    rating_scale_max = fields.Integer(
        string='Max Scale', related='question_id.rating_scale_max', readonly=True)
    rating_label_min = fields.Char(
        string='Min Label', related='question_id.rating_label_min', readonly=True)
    rating_label_max = fields.Char(
        string='Max Label', related='question_id.rating_label_max', readonly=True)

    # Rating Scale (1 to 5)
    rating = fields.Selection([
        ('1', '1 - Poor'),
        ('2', '2 - Fair'),
        ('3', '3 - Satisfactory'),
        ('4', '4 - Very Good'),
        ('5', '5 - Excellent'),
    ], string='Rating Scale (1-5)', help="Select rating from 1 (Poor) to 5 (Excellent).")
    rating_value = fields.Float(
        string='Numeric Rating', compute='_compute_rating_value', store=True)
    comments = fields.Char(string='Remarks / Feedback')

    @api.depends('rating')
    def _compute_rating_value(self):
        for rec in self:
            rec.rating_value = float(rec.rating) if rec.rating else 0.0
